using Confectory.Core;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

// Explicit selected-source snapshot/copy only. Never edits a source declaration/body.
internal static class ImplementationCopy
{
 public static JsonObject Query(JsonObject request,Func<Element,string> format)
 {
  string project=Path.GetFullPath(request["project"]!.GetValue<string>()),root=Path.GetDirectoryName(project)!,action=request["action"]!.GetValue<string>();
  var observations=new SortedDictionary<string,string>(StringComparer.Ordinal);int bytes=0,bodyReads=0;
  byte[] ReadBytes(string path){path=Path.GetFullPath(path);for(FileSystemInfo? entry=new FileInfo(path);entry is not null;entry=entry is FileInfo file?file.Directory:((DirectoryInfo)entry).Parent)if(entry.LinkTarget is not null)throw new ArgumentException("Implementation copy cannot traverse links");var info=new FileInfo(path);if(!info.Exists||info.Length>1048576)throw new IOException("Bounded implementation copy source required");var raw=File.ReadAllBytes(path);string hash=JsonData.HashBytes(raw);if(observations.TryGetValue(path,out string? prior)){if(prior!=hash)throw new InvalidOperationException("Copy source changed while reading");}else{bytes=checked(bytes+raw.Length);if(bytes>2097152||observations.Count>=64)throw new ArgumentException("Implementation copy source budget");observations[path]=hash;}return raw;}
  string Read(string path)=>new UTF8Encoding(false,true).GetString(ReadBytes(path));
  var statistics=new BuildStatistics();var registry=new Registry(project,new Documents("",statistics,ReadBytes),statistics);
  string feature=request["feature"]!.GetValue<string>();var fn=registry.Get(feature,"function");if(fn.Signature is null)throw new ArgumentException("Explicit slot function contract required");
  JsonObject Finish(JsonObject result){foreach(var row in observations)if(JsonData.HashBytes(File.ReadAllBytes(row.Key))!=row.Value)throw new IOException("Copy source changed after preparation");result["observations"]=new JsonArray(observations.Select(row=>(JsonNode)new JsonObject{["path"]=row.Key,["sha256"]=row.Value}).ToArray());result["bodyReads"]=bodyReads;result["sourceWritten"]=false;result["compiled"]=false;return result;}
  Element Source(string id){var source=registry.Effective(registry.Get(id,"implementation").Id);if(source.Function!=feature||source.Signature is null||!source.Signature.Matches(fn.Signature))throw new ArgumentException("Implementation must keep this exact public function contract");return source;}
  if(action=="catalog"){
   var ids=request["ids"]!.AsArray();if(ids.Count>16)throw new ArgumentException("Bounded selected implementation candidates required");var rows=new JsonArray();foreach(string id in ids.Select(n=>n!.GetValue<string>()).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal)){var source=Source(id);foreach(var body in source.Bodies.OrderBy(p=>p.Key,StringComparer.Ordinal))rows.Add(new JsonObject{["id"]=id,["target"]=body.Key,["sourceKind"]=body.Value.SourceKind,["bodyOrigin"]=body.Value.Origin,["description"]=source.Description,["registered"]=PackPaths.Namespace(id)!=registry.Project.Namespace});}return Finish(new JsonObject{["rows"]=rows});
  }
  if(action!="prepare")throw new ArgumentException("Explicit copy action required");
  string selected=request["source"]!.GetValue<string>(),target=request["target"]!.GetValue<string>(),implementation=request["implementation"]!.GetValue<string>(),ownerId=request["owner"]!.GetValue<string>();
  if(!Regex.IsMatch(target,@"\A[A-Za-z_][A-Za-z_0-9.-]*\z")||!implementation.StartsWith(registry.Project.Namespace+"::",StringComparison.Ordinal)||!Regex.IsMatch(implementation[(registry.Project.Namespace.Length+2)..],@"\A[A-Za-z_][A-Za-z_0-9]*\z"))throw new ArgumentException("Explicit target and new owned implementation required");
  var owner=new Parser(request["ownerText"]!.GetValue<string>(),"<copy-owner>").ParseElement();if(owner.Id!=ownerId||owner.Kind!="object"||PackPaths.Namespace(ownerId)!=registry.Project.Namespace)throw new ArgumentException("Owned object copy target required");
  var original=Source(selected);if(!original.Bodies.TryGetValue(target,out var bodySource))throw new ArgumentException("Select a declared body target, without platform guessing");
  string graphPath="blueprints/"+implementation[(registry.Project.Namespace.Length+2)..]+".graph.json",bodyPath=PackPaths.Owned(Path.GetDirectoryName(registry.Paths[PackPaths.Namespace(bodySource.Origin)])!,bodySource.Path);
  var copy=new Parser(format(original),"<copy-template>").ParseElement();copy.Id=implementation;copy.Parent=null;copy.Bodies=new(){[target]=new Body(graphPath,new(),implementation,"blueprint")};
  // Explicit imported scopes affect the copied body's meaning. Observe their
  // published inheritance/module closure without activating any implementation.
  foreach(string scope in copy.Imports.Values.Where(i=>i.Scope is not null).Select(i=>i.Scope!).Distinct(StringComparer.Ordinal))registry.Effective(scope);
  var context=FeatureBlueprint.ImplementationContext(copy);var contracts=new JsonObject();foreach(string id in copy.Imports.Values.Select(i=>i.Id).Distinct(StringComparer.Ordinal)){var called=registry.Get(id,"function");contracts[id]=Read(called.Loc.File);}
  var records=new JsonArray();JsonObject graph;JsonObject? originalGraph=null;
  if(bodySource.SourceKind=="csharp"){
   bodyReads++;string source=Read(bodyPath);var arguments=new JsonObject();for(int i=0;i<copy.Signature!.Args.Count;i++)if(!copy.Signature.Args[i].IsOut)arguments[copy.Signature.Args[i].Name]=new JsonObject{["input"]=fn.Signature.Args[i].Name};
   string nodePath="nodes/"+implementation[(registry.Project.Namespace.Length+2)..]+".body.node.json";
   graph=new JsonObject{["schema"]=1,["profile"]=FeatureBlueprint.HasObjectSignature(fn.Signature)?FeatureBlueprint.PropertyProfile:copy.Signature.Args.Any(p=>p.Mode is "out" or "ref")?FeatureBlueprint.ExternalRefsProfile:FeatureBlueprint.ImplicitProfile,["feature"]=feature,["contractHash"]=FeatureBlueprint.ContractHash(fn),["entry"]="body",["nodes"]=new JsonArray(new JsonObject{["id"]="body",["kind"]="code",["control"]="next",["intent"]=original.Description.Length>0?original.Description:"기존 구현 복사",["signature"]=FeatureBlueprint.SignatureDocument(copy.Signature),["arguments"]=arguments,["implementation"]=nodePath,["implementationContext"]=context.DeepClone(),["sourceIdentity"]=bodyPath}),["edges"]=new JsonArray(new JsonObject{["from"]="body",["port"]="next",["to"]="exit:return"}),["exits"]=new JsonObject{["return"]=fn.Signature.Return=="void"?null:new JsonObject{["node"]="body"}}};
   records.Add(new JsonObject{["id"]="body",["relative"]=nodePath,["record"]=new JsonObject{["schema"]=1,["node"]="body",["source"]=source}});
  }else if(bodySource.SourceKind=="blueprint"){
   bodyReads++;graph=JsonNode.Parse(Read(bodyPath))!.AsObject();if(graph["feature"]?.ToString()!=feature||graph["nodes"] is not JsonArray graphNodes||graphNodes.Any(n=>n?["kind"]?.ToString() is not ("code" or "call" or "export")||!(n["control"]?.ToString()=="next"||n["kind"]?.ToString()=="call"&&n["control"]?.ToString()=="switch"&&n["postCall"]?["mode"]?.ToString()=="execution-enum")))throw new ArgumentException("This original graph shape is not connected to the serial copy editor yet");
   originalGraph=graph.DeepClone().AsObject();foreach(var node in graphNodes){if(node!["kind"]?.ToString()=="export")continue;if(node!["implementationContext"] is JsonObject copiedContext){if(copiedContext["implementation"]?.ToString()!=selected&&copiedContext["implementation"]?.ToString()!=bodySource.Origin)throw new ArgumentException("Copy preserves only its own whole-body method context; other contexts need explicit support");node["implementationContext"]=context.DeepClone();}if(node["kind"]!.ToString()=="call"){string called=node["feature"]!.ToString();contracts[called]=Read(registry.Get(called,"function").Loc.File);continue;}string old=PackPaths.Owned(Path.GetDirectoryName(bodyPath)!,node["implementation"]!.ToString());bodyReads++;var record=JsonNode.Parse(Read(old))!.AsObject();string name=node["id"]!.ToString(),relative="nodes/"+implementation[(registry.Project.Namespace.Length+2)..]+"."+JsonData.Digest(name)[..12]+".node.json";node["implementation"]=relative;records.Add(new JsonObject{["id"]=name,["relative"]=relative,["record"]=record});}
  }else throw new ArgumentException("Supported C# or Blueprint source required");
  if(originalGraph is not null){
   var sourceDefinitions=FeatureBlueprint.Execute(new JsonObject{["operation"]="featureBlueprintNodes",["featureSource"]=Read(fn.Loc.File),["featureContracts"]=contracts.DeepClone(),["implementationContext"]=FeatureBlueprint.ImplementationContext(original),["graph"]=originalGraph});if(sourceDefinitions["state"]?.ToString()!="node-definitions")throw new ArgumentException(sourceDefinitions.ToJsonString());
   foreach(var entry in records){string id=entry!["id"]!.ToString();var record=entry["record"]!;BlueprintDocuments.Validate(implementation+"/body:"+target+"/node:"+id,"blueprint-node",record.ToJsonString());if(record["definitionHash"]?.ToString()!=sourceDefinitions["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==id)!["definitionHash"]!.ToString())throw new InvalidOperationException("Confirm the source Blueprint against its current contract before copying; stale code is preserved");}
  }
  JsonObject Definitions()=>FeatureBlueprint.Execute(new JsonObject{["operation"]="featureBlueprintNodes",["featureSource"]=Read(fn.Loc.File),["featureContracts"]=contracts.DeepClone(),["implementationContext"]=context.DeepClone(),["graph"]=graph.DeepClone()});
  var beforeEdits=Definitions();if(beforeEdits["state"]?.ToString()!="node-definitions")throw new ArgumentException(beforeEdits.ToJsonString());
  foreach(var record in records)record!["record"]!["definitionHash"]=beforeEdits["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==record["id"]!.ToString())!["definitionHash"]!.DeepClone();
  var reapplied=ImplementationCopyEdits.Apply(graph,records,request["edits"]?.AsArray()??new JsonArray(),copy,implementation,fn.Signature!);
  graph["copySource"]=new JsonObject{["implementation"]=selected,["target"]=target,["bodyOrigin"]=bodySource.Origin,["sourceKind"]=bodySource.SourceKind};
  var definitions=FeatureBlueprint.Execute(new JsonObject{["operation"]="featureBlueprintNodes",["featureSource"]=Read(fn.Loc.File),["featureContracts"]=contracts,["implementationContext"]=context,["graph"]=graph.DeepClone()});if(definitions["state"]?.ToString()!="node-definitions")throw new ArgumentException(definitions.ToJsonString());
  foreach(var entry in records.Where(r=>reapplied.Contains(r!["id"]!.ToString()))){string id=entry!["id"]!.ToString();entry["record"]!["definitionHash"]=definitions["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==id)!["definitionHash"]!.DeepClone();}
  var recordMap=new JsonObject();foreach(var record in records)recordMap[record!["id"]!.ToString()]=record["record"]!.DeepClone();
  var checkedBody=FeatureBlueprint.Execute(new JsonObject{["operation"]="featureBlueprintDescribe",["featureSource"]=Read(fn.Loc.File),["featureContracts"]=contracts.DeepClone(),["implementationContext"]=FeatureBlueprint.ImplementationContext(copy),["graph"]=graph.DeepClone(),["implementations"]=recordMap});
  if(checkedBody["state"]?.ToString()!="source-ready"||checkedBody["nodes"]!.AsArray().Any(n=>n!["status"]?.ToString() is "missing" or "stale"))throw new InvalidOperationException("Every copied body record/import/wrapper must match the final contract; inputs retained");
  var projected=new JsonArray();foreach(var node in graph["nodes"]!.AsArray()){
   string id=node!["id"]!.ToString();var definition=definitions["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==id)!;var row=new JsonObject{["id"]=id,["kind"]=node["kind"]!.DeepClone(),["control"]=node["control"]!.DeepClone(),["intent"]=node["intent"]?.DeepClone(),["signature"]=definition["definition"]!["signature"]!.DeepClone(),["definitionHash"]=definition["definitionHash"]!.DeepClone(),["implementationContext"]=definition["definition"]!["implementationContext"]?.DeepClone(),["calledFeature"]=definition["definition"]!["calledFeature"]?.DeepClone(),["outputs"]=definition["outputs"]!.DeepClone(),["displayName"]=node["displayName"]?.DeepClone()??JsonValue.Create(id),["renameable"]=node["implementationContext"] is null};
   var arguments=new JsonArray();foreach(var arg in definition["definition"]!["signature"]!["args"]!.AsArray().Where(a=>a!["mode"]?.ToString()!="out"))arguments.Add(new JsonObject{["name"]=arg!["name"]!.DeepClone(),["type"]=arg["type"]!.DeepClone(),["mode"]=arg["mode"]?.DeepClone(),["valueJson"]=node["arguments"]?[arg["name"]!.ToString()]?.ToJsonString()??"null"});row["arguments"]=arguments;
   foreach(string field in new[]{"wrapperEditor","postCallEditor","postCallStale","postCallSignatureMatches"})row[field]=definition[field]?.DeepClone();row["postCall"]=definition["definition"]?["postCall"]?.DeepClone();row["executionEnum"]=node["executionEnum"]?.DeepClone();row["callAbiAvailable"]=false;
   if(node["kind"]!.ToString()=="code"){var record=records.Single(n=>n!["id"]!.ToString()==id)!["record"]!;row["source"]=record["source"]!.DeepClone();row["sourceStatus"]=record["definitionHash"]!.ToString()==definition["definitionHash"]!.ToString()?"available":"stale";row["helpers"]=record["helpers"]?.DeepClone()??JsonValue.Create("");}else row["sourceStatus"]=node["kind"]?.ToString()=="export"?"output-assignment":"feature-reference";if(node["kind"]?.ToString()=="export")row["output"]=node["output"]!.DeepClone();
   if(copy.Signature!.Args.Any(a=>a.Mode is "ref" or "out")&&node["implementationContext"] is not null)row["forwardCallerStorage"]=true;projected.Add(row);
  }
  var exits=new JsonArray();foreach(var exit in graph["exits"]!.AsObject())exits.Add(new JsonObject{["name"]=exit.Key,["valueJson"]=exit.Value?.ToJsonString()??"null"});
  var localRows=new JsonArray();foreach(var local in definitions["locals"]!.AsArray()){var row=new JsonObject{["id"]=local!["id"]!.DeepClone(),["name"]=local["name"]!.DeepClone(),["type"]=local["type"]!.DeepClone()};if(local.AsObject().ContainsKey("source"))row["sourceJson"]=local["source"]!.ToJsonString();else row["initialJson"]=local["initial"]!["constant"]?.ToJsonString()??"null";localRows.Add(row);}
  var preview=new JsonObject{["id"]=null,["rootId"]=implementation+"/body:"+target,["feature"]=feature,["signature"]=FeatureBlueprint.SignatureDocument(fn.Signature),["profile"]=graph["profile"]!.DeepClone(),["entry"]=graph["entry"]?.DeepClone(),["nodes"]=projected,["edges"]=graph["edges"]!.DeepClone(),["exits"]=exits,["locals"]=localRows,["outputOrder"]=graph["outputOrder"]?.DeepClone(),["implementationDescription"]=copy.Description,["diagnostics"]=new JsonObject{["state"]="private-copy"}};
  owner.Provides[feature]=new ElementReference(implementation,new(),ownerId);var result=Finish(new JsonObject{["owner"]=format(owner),["implementation"]=format(copy),["graph"]=graph,["graphPath"]=graphPath,["records"]=records,["signature"]=FeatureBlueprint.SignatureDocument(fn.Signature),["source"]=selected,["target"]=target,["sourceKind"]=bodySource.SourceKind,["bodyOrigin"]=bodySource.Origin,["preview"]=preview});return result;
 }
}
